        c = new C();
        token = new ERC20Mock();
    }

    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256[] memory v) public {
        // Bound input arrays to reasonable size
        vm.assume(_tos.length > 0 && _tos.length <= 10);
        vm.assume(v.length == _tos.length);

        // Bound amounts to avoid overflow issues (they will be very large)
