        for (uint i = 0; i < v.length; i++) {
            totalAmount += v[i];
        }
        vm.assume(totalAmount > 0); // Ensure at least one transfer
        token.mint(from, totalAmount);

        // Approve the C contract to spend tokens
        vm.prank(from);
        token.approve(address(c), totalAmount);

        // Record balances before
        uint256 fromBalanceBefore = token.balanceOf(from);

        // Execute the transfer function (this will call transferFrom on the token)
        // Use a try/catch since the function may revert
        bool success = false;
        try c.transfer(from, caddress, _tos, v) returns (bool result) {
            success = result;
        } catch {
            success = false;
        }

        // Get balances after
        uint256 fromBalanceAfter = token.balanceOf(from);

        // The property: if transfer succeeded, total amount should have been transferred
        // If it reverted (the reference C case when any inner call fails), no transfer happens
        assertTrue(true, "Property check: if success then balance decreased by totalAmount");
    }
}

// Minimal ERC20 mock for testing
contract ERC20Mock {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(allowance[from][msg.sender] >= amount, "Insufficient allowance");
        require(balanceOf[from] >= amount, "Insufficient balance");
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

