import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address token, address[] memory _tos, uint[] memory v) public {
        // Assume arrays have same length and non-empty
        vm.assume(_tos.length > 0 && _tos.length == v.length);
        // Ensure token is a contract with balanceOf function
        vm.assume(token != address(0) && token.code.length > 0);

        // Record initial balances of all recipients
        uint[] memory initialBalances = new uint[](_tos.length);
        for(uint i = 0; i < _tos.length; i++) {
            (bool success, bytes memory data) = token.staticcall(abi.encodeWithSignature("balanceOf(address)", _tos[i]));
            vm.assume(success && data.length == 32);
            initialBalances[i] = abi.decode(data, (uint));
        }

        // Call transfer
        c.transfer(from, token, _tos, v);

        // Check final balances not increased
        bool anyIncreased = false;
        for(uint i = 0; i < _tos.length; i++) {
            (bool success, bytes memory data) = token.staticcall(abi.encodeWithSignature("balanceOf(address)", _tos[i]));
            require(success && data.length == 32);
            uint finalBalance = abi.decode(data, (uint));
            if(finalBalance > initialBalances[i]) {
                anyIncreased = true;
                break;
            }
        }
        assertTrue(!anyIncreased, "Balance of at least one recipient increased");
    }
}

